    + 'local ' + t + ' = {}\n'
    + t + '.__index = ' + t + '\n\n'
    + 'function ' + t + '.new(stream)\n'
    + '  return setmetatable({ stream = stream }, ' + t + ')\nend\n\n'
    + '--- Next response; raises EndOfStream at the end of the call.\n'
    + 'function ' + t + ':recv()\n'
